/**
 * Exercise illustrations (roadmap item 13, PR 2). A reviewed, explicit mapping from library exercise ids to openly
 * licensed start/end illustrations that are self-hosted under public/exercise-media/ (same origin, so the CSP's
 * `img-src 'self'` covers them). Custom and unmapped exercises return null and keep the movement-pattern glyph.
 *
 * Source and licence: Everkinetic open data, CC BY-SA 4.0 (docs/THIRD_PARTY_MEDIA.md). The credit line shown next to an
 * illustration is required by the licence. Files are generated by scripts/build-exercise-media.mjs.
 */
import mapping from './exerciseMedia.json';

/** Bump together with MEDIA_VERSION in scripts/build-exercise-media.mjs when files change (they're cached immutably). */
export const EXERCISE_MEDIA_BASE = '/exercise-media/v1/';

/** How an illustration differs from the library exercise (load only; the movement is the same). */
export type MediaVariant = 'withBarbell' | 'withoutLoad';

export interface ExerciseMedia {
  /** Start and end position frames (square, ≤ 480 px). */
  frames: readonly [string, string];
  /** 96 px end-position frame for the workout logger. */
  thumb: string;
  variant?: MediaVariant;
}

interface MappingEntry {
  source: string;
  sourceId: string;
  sourceName: string;
  variant?: string;
}

export const EXERCISE_MEDIA_MAPPING: Readonly<Record<string, MappingEntry>> = mapping.exercises;

/**
 * Licence credit for the illustration set. Every illustration shows the author and licence; the author links to the
 * in-app credits page (CREDITS_PATH), which carries the full attribution: source, creator, licence and our changes.
 */
export const EXERCISE_MEDIA_CREDIT = {
  author: 'Everkinetic',
  site: 'everkinetic.com',
  creator: 'Greg Priday',
  sourceUrl: 'https://github.com/everkinetic/data',
  license: 'CC BY-SA 4.0',
  licenseUrl: 'https://creativecommons.org/licenses/by-sa/4.0/',
} as const;

/** In-app credits & licences page (works offline; linked from illustrations, exercise lists and Settings). */
export const CREDITS_PATH = '/credits';
export const CREDITS_ILLUSTRATIONS_ID = 'exercise-illustrations';

export function mediaDir(entry: Pick<MappingEntry, 'source' | 'sourceId'>): string {
  return `${entry.source === 'everkinetic' ? 'ek' : entry.source}-${entry.sourceId}`;
}

const cache = new Map<string, ExerciseMedia>();

/** The illustration for a library exercise, or null (custom/unmapped exercises). */
export function exerciseMedia(exerciseId: string | undefined): ExerciseMedia | null {
  if (!exerciseId || !Object.hasOwn(EXERCISE_MEDIA_MAPPING, exerciseId)) return null;
  const hit = cache.get(exerciseId);
  if (hit) return hit;
  const entry = EXERCISE_MEDIA_MAPPING[exerciseId];
  const base = `${EXERCISE_MEDIA_BASE}${mediaDir(entry)}/`;
  const media: ExerciseMedia = {
    frames: [`${base}0.webp`, `${base}1.webp`],
    thumb: `${base}thumb.webp`,
    variant: entry.variant === 'withBarbell' || entry.variant === 'withoutLoad' ? entry.variant : undefined,
  };
  cache.set(exerciseId, media);
  return media;
}
